UPDATE `quest_template_locale` SET `QuestDescription`='Я прибыла в Награнд, чтобы найти работников для Археологического общества Хитрой Шестеренки. Мы – археологическое подразделение Картеля Хитрой Шестеренки.$b$bЗанимаемся поиском артефактов, реликвий, антиквариата и прочих подобных штуковин, какие только можно найти в Награнде! На данный момент нам нужны геодезисты, землекопы, искатели приключений... в общем, все нужны!$b$bТак что если ты не прочь запачкать руки и подзаработать, поговори с Газмольфом Прохлаждайсом в ущелье Каменных Скал. Этот гоблин руководит всей нашей экспедицией!', `VerifiedBuild`=25549 WHERE (`ID`=34810 AND `locale`='ruRU');
