UPDATE `quest_template_locale` SET `QuestDescription`='Каждый раз, когда из Каменного Молота убегает гладиатор, за ним отправляют опытных охотников на рабов.$b$bЯ считаю себя опытным воином, несколько лет я отдал арене.$b$bНо охотники на рабов делают для надзирателей подвески, по которым они могут отследить нас повсюду. А потом убить, когда мы уснем или просто утратим бдительность.$b$bЯ не имею права просить тебя о таком, но все же – ты можешь пойти в Каменный Молот и забрать оттуда подвески?', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=34698 AND `locale`='ruRU');
