UPDATE `quest_template_locale` SET `QuestDescription`='Самое главное – безопасность моего народа.$B$BСкорее всего, Нер''зул запер пленников в Шаз''гуле, своей крепости на юго-западе.$B$BЯ не хочу применять против него насилие, но возможно, мне придется это сделать.$B$BВстретимся на Сумеречной поляне, $n, и попробуем освободить узников.', `VerifiedBuild`=25549 WHERE (`ID`=33072 AND `locale`='ruRU');
