UPDATE `quest_template_locale` SET `LogDescription`='Создайте комплект для установки тележки с супом с лапшой.$BСоберите 20 луж хмеля, победив хмелементалей на хмелеварне Буйных Портеров.', `QuestDescription`='Так держать, $n. Вижу, ты $gготов:готова; и дальше изучать тайны супа Линь.$B$BНасколько я понимаю, для приготовления бульона семья Линь использовала хмель Буйных Портеров.$B$BДумаю, тебе придется сделать себе собственную тележку с супом с лапшой, а затем отправиться на хмелеварню Буйных Портеров, чтобы позаимствовать немного разлитого хмеля.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=33024 AND `locale`='ruRU');
