UPDATE `quest_template_locale` SET `QuestDescription`='Эти могущественные порождения ша тебе не одолеть в одиночку.$b$bБоюсь, от меня будет мало пользы в поле боя, но у меня есть одна идея.$b$bЭта гигантская нефритовая статуя должна была превратиться в живую змею, одного из наших почитаемых Небожителей. Это сооружение насыщено особой энергией, которая может существенно ослабить этих противников.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=30502 AND `locale`='ruRU');
