UPDATE `quest_template_locale` SET `QuestDescription`='Хочешь денек побыть шелкоделом?$b$bПрежде всего тебе понадобятся листья шелковицы. Их можно набрать в зарослях тутовника на северо-западе.$b$bЛистья ты $gдолжен:должна; скормить голодным шелкопрядам – они в яме к западу отсюда.$b$bИ, наконец, возьми немного шелка-сырца из хижины, стоящей в южной части фермы.$b$bЖелаю удачи!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=30072 AND `locale`='ruRU');
