UPDATE `quest_template_locale` SET `LogDescription`='Явитесь к Кадраку на заставу Мор''шан, что на границе между Северными степями и Ясеневым лесом.', `QuestDescription`='Кадраку с заставы Мор''шан нужна твоя помощь!$B$BЗастава расположена на границе Северных степей и Ясеневого леса – прямо на линии фронта.$B$BМы ведем кровопролитную борьбу с Альянсом, чтобы выжить лесных эльфов из леса и завладеть ресурсами на благо Орды!$B$BЧтобы добраться до заставы Мор''шан, следуй по Золотому Пути на север от Перекрестка в Северных степях.$B$bСудьба зовет!', `VerifiedBuild`=25549 WHERE (`ID`=28876 AND `locale`='ruRU');
