UPDATE `quest_template_locale` SET `LogTitle`='Приказ вождя: Болото печали!', `LogDescription`='Явитесь к торговому барону Сереблексу в Веслотопи на Болоте печали.', `QuestDescription`='Настоящим повелением всем годным к службе воинам Орды приказано явиться к торговому барону Сереблексу в Веслотопь.$B$BЛюбыми средствами убедите барона продолжить поставки оружия и боеприпасов нашей армии в необходимом объеме!$B$BДля того чтобы попасть на Болото печали, следуйте по дороге из Пылающих степей на юго-восток, минуя Красногорье. После прибытия на место отыщите барона в его курортной резиденции.$B$BСудьба зовет!', `VerifiedBuild`=25549 WHERE (`ID`=28677 AND `locale`='ruRU');
