UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его королевского высочества короля Андуина Ринна всем членам Альянса, способным держать оружие, надлежит отрапортовать Джеку Глыбоногу на Передовой Братства Тория.$b$bШРУ сообщает о том, что дворфы Черного Железа в Тлеющем ущелье готовятся к нападению. Вашим заданием будет разведать об этом все, что сможете, и помешать их действиям.$b$bЧтобы попасть в Тлеющее ущелье, идите по дороге, что ведет из Бесплодных земель на запад.$b$bЗа честь и славу Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=28582 AND `locale`='ruRU');
