UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к пилоту Большеногу на заставу у Южных врат.$b$bИз-за разрушения Каменной Плотины и повышенной активности троггов и кобольдов силы горных пехотинцев на пределе. Они отчаянно нуждаются в подкреплении! Чтобы добраться до заставы у Южных врат, пройдите через Южные врата, которые находятся в восточной части Дун Морога.$b$bЗа честь и славу Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=28567 AND `locale`='ruRU');
