UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его королевского высочества короля Андуина Ринна все годные к военной службе граждане Альянса обязаны явиться к Келси Стализвон в Прибамбасск.$b$bАльянсу требуется ваша помощь, чтобы отвоевать земли у местного барона и получить доступ к ценным ресурсам. Чтобы добраться до Прибамбасска, отправляйтесь на юг из Мерцающих глубин, что в Тысяче Игл.$b$bЗа честь и славу Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=28507 AND `locale`='ruRU');
