UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его высочества Короля Андуина Ринна, всем дееспособным воинам Альянса надлежит незамедлительно явиться к Кариссии Лунной Охотнице в Новый Таланаар на границе Фераласа и Тысячи Игл.$B$BЧасовым нужна ваша помощь, чтобы прогнать мародеров из клана Зловещего Тотема, что бесчинствуют в тамошних землях. Чтобы добраться до Нового Таланаара, идите на восточную окраину Фераласа, к границе с Тысячей Игл.$B$BВо имя славы и чести Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=28503 AND `locale`='ruRU');
