UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его королевского высочества короля Андуина Ринна все годные к военной службе подданные Альянса должны явиться к жрице Дентарии в Лор''данел, что на Темных берегах.$B$BНарод Лор''данела взывает о вашей помощи в спасении уцелевших жителей Аубердина и борьбе против культа Сумеречного Молота! Поговорите с Веспристом, укротителем гиппогрифов из деревни Рут''теран, что находится рядом с Дарнасом, и он отправит вас на Темные берега.$B$BЗа честь и славу Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=28490 AND `locale`='ruRU');
