UPDATE `quest_template_locale` SET `QuestDescription`='Джонси говорит, вам с ним надо попасть на вершину горы.$B$BПросто так вам не подняться: там столько этих солдат... больше, чем крокодилов в Вир''наале.$B$BКое-кому из моих друзей удалось раздобыть пару вражеских машин. Так что артиллерией вы обеспечены, я уже договорился.$B$BИдите на север, поднимитесь по склону, и эти машины уже ждут вас там.$B$BУдачи, ребята!', `VerifiedBuild`=25549 WHERE (`ID`=28482 AND `locale`='ruRU');
