UPDATE `quest_template_locale` SET `LogTitle`='Приказ вождя: предгорья Хилсбрада!', `LogDescription`='Отчитайтесь верховному палачу Дарталии у Южных врат в предгорьях Хилсбрада.', `QuestDescription`='Всем годным к военной службе подданным Орды надлежит явиться к верховному палачу Дарталии в предгорья Хилсбрада к Южным вратам. Боевая машина Отрекшихся движется вперед и вперед, защищая Лордерон!$b$bЧтобы добраться до Южных врат, нужно идти по дороге на юг через Серебряный бор, а на развилке повернуть на восток, на дорогу, ведущую к предгорьям Хилсбрада.$b$bВперед, $gбрат:сестра;! Судьба зовет!', `VerifiedBuild`=25549 WHERE (`ID`=28089 AND `locale`='ruRU');
