UPDATE `quest_template_locale` SET `QuestDescription`='По приказу его королевского высочества короля Андуина Ринна всем годным к службе гражданам Альянса надлежит явиться к укротителю грифонов Разящему Когтю в питомник на Заоблачном пике.$B$BНаши братья по оружию из Альянса взывают к вам о помощи, чтобы уберечь свою горячо любимую родину от посягательств Орды. Отправляйтесь на север с нагорья Арати и по горному перевалу дворфов проследуйте на дорогу, что ведет на северо-запад к Заоблачному пику.$B$BЗа честь и славу Альянса!', `VerifiedBuild`=25549 WHERE (`ID`=26542 AND `locale`='ruRU');
