UPDATE `quest_template_locale` SET `QuestDescription`='Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить силу кристаллов, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=26039 AND `locale`='ruRU');
