UPDATE `quest_template_locale` SET `QuestDescription`='Служанка Элуны! Она еще прекрасней, чем говорят.$B$BЛегенды, сложенные об этой реликвии, всплывают в вашей памяти, когда вы приближаетесь к ней:$B$BВ древние времена оружие врагов после боя сбрасывали в воду, чтобы получить божественный дар...$B$BПока вы вспоминаете ритуал, блеск стали от ближайшей стойки с оружием привлекает ваше внимание...', `PortraitGiverText`='', `VerifiedBuild`=25549 WHERE (`ID`=14357 AND `locale`='ruRU');
