UPDATE `quest_template_locale` SET `QuestDescription`='Превосходно!$b$bТеперь-то мы покажем этим эльфам, на что способна Орда, загнанная в угол.$b$bСлушай меня внимательно, $n, и никому не проболтайся!$b$bСаурфанг, несомненно, одобрит подобные действия, как только увидит результаты, но если кто-нибудь узнает заранее, что мы планируем, – не сносить нам головы!$b$b<Драака протягивает вам спешно нацарапанную записку.>$b$bЭто отнесешь Дурану. Он сейчас в шахтах на севере. Дальнейшие указания получишь у него.', `PortraitGiverText`='Ни в коем случае не заглядывай в эту записку!', `VerifiedBuild`=25549 WHERE (`ID`=13751 AND `locale`='ruRU');
