UPDATE `quest_template_locale` SET `LogDescription`='Отправляйтесь к Застывшей лавине в низине Шолазар и используйте руну "Омега", чтобы привести в действие Этимидиана. Используйте его, чтобы уничтожить 200 прислужников Плети, Битиуса Ваятеля Плоти, Ургрета из Тысячи Могил и Градохлада.$B$BВыполнив задание, поговорите с Аватарой Фрейи в низине Шолазар.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=12546 AND `locale`='ruRU');
