UPDATE `quest_template_locale` SET `LogDescription`='Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Колючем холме.', `QuestDescription`='Бугаи устроили полигон для учений пожарной бригады около деревни. В нынешние времена дома Колючего холма часто горят, так что помоги им и поупражняйся в тушении пожара!$B$BИди на запад от Колючего холма, за стеной деревни сразу сверни направо. Найди полигон, хватай ведро и туши учебный пожар!', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=11361 AND `locale`='ruRU');
