UPDATE `quest_template_locale` SET `QuestDescription`='Мой наставник прислал меня сюда искать помощи, но увы – меня не выпускают из Нижнего Города, а от тех, кто часто посещает это заведение, толку, мягко говоря, мало.$B$BНо ты другое дело, ты больше $Gпохож:похожа; на тех, кто не боится приключений. Если ты не против помочь нам, поговори с верховным магом Альтуром близ старой обители Медива, Каражана. $B$BА я пока постараюсь получить доступ к другим частям города. Говорят, тут сейчас находится один из наших старых помощников.', `VerifiedBuild`=25549 WHERE (`ID`=11216 AND `locale`='ruRU');
