UPDATE `quest_template_locale` SET `QuestDescription`='Охота на личинок шелкокрыла – нелегкое дело для юных воинов, но хорошо то, что даже если им не удастся снять кокон с личинки, нам пригодятся и крылья вылупившихся шелкокрылов.$b$bНа самом-то деле крылья идут на куда больше изделий, чем коконы, и их никогда не бывает слишком много.$b$bЕсли пойдешь прогуляться, я была бы очень благодарна, если бы ты $Gпринес:принесла; мне некоторое количество крыльев.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=10618 AND `locale`='ruRU');
