UPDATE `quest_template_locale` SET `LogDescription`='Убейте 8 чумнокостных погромщиков и вернитесь к следопыту Джаеле на Тропе Мертвых в лесах Вечной Песни.', `QuestDescription`='Полоса выжженной земли, которая тянется через леса Вечной Песни, как постоянное напоминание о том дне, когда Артас привел Плеть в наш возлюбленный город...$b$bЭто хуже, чем бельмо на глазу: даже теперь по ней в Луносвет приходят прислужники Плети из Призрачных земель.$b$bСтупай, $n, и помоги моим воинам убивать лишенную разума нежить, которая приходит Тропой Мертвых.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=8475 AND `locale`='ruRU');
